-- Segment 3: structured Bulk exercise library. Existing workouts continue to use
-- their stored exercise names; this catalog is additive and does not rewrite history.
CREATE TABLE public.bulk_exercises (
  id text PRIMARY KEY DEFAULT ('custom:' || gen_random_uuid()::text),
  owner_id uuid DEFAULT auth.uid() REFERENCES auth.users(id) ON DELETE CASCADE,
  slug text NOT NULL,
  name text NOT NULL,
  primary_muscle text NOT NULL,
  secondary_muscles text[] NOT NULL DEFAULT '{}',
  equipment text[] NOT NULL,
  movement_pattern text NOT NULL,
  category text NOT NULL DEFAULT 'strength',
  supports_unilateral boolean NOT NULL DEFAULT false,
  default_unilateral_mode text NOT NULL DEFAULT 'bilateral',
  is_bodyweight boolean NOT NULL DEFAULT false,
  is_system boolean NOT NULL DEFAULT false,
  active boolean NOT NULL DEFAULT true,
  min_experience text NOT NULL DEFAULT 'beginner',
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT bulk_exercises_name_ck CHECK (char_length(btrim(name)) BETWEEN 2 AND 80),
  CONSTRAINT bulk_exercises_slug_ck CHECK (slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'),
  CONSTRAINT bulk_exercises_primary_muscle_ck CHECK (primary_muscle = ANY (ARRAY['chest','lats','upper_back','traps','front_delts','side_delts','rear_delts','biceps','triceps','forearms','quads','hamstrings','glutes','calves','adductors','abductors','abs','obliques','lower_back'])),
  CONSTRAINT bulk_exercises_secondary_muscles_ck CHECK (secondary_muscles <@ ARRAY['chest','lats','upper_back','traps','front_delts','side_delts','rear_delts','biceps','triceps','forearms','quads','hamstrings','glutes','calves','adductors','abductors','abs','obliques','lower_back']::text[] AND NOT primary_muscle = ANY (secondary_muscles)),
  CONSTRAINT bulk_exercises_equipment_ck CHECK (cardinality(equipment) > 0 AND equipment <@ ARRAY['barbell','dumbbell','cable','machine','smith_machine','bench','pull_up_bar','bodyweight','kettlebell','resistance_band','plate','trap_bar','ez_bar']::text[]),
  CONSTRAINT bulk_exercises_movement_pattern_ck CHECK (movement_pattern = ANY (ARRAY['horizontal_push','vertical_push','horizontal_pull','vertical_pull','squat','hinge','lunge','knee_extension','knee_flexion','hip_extension','hip_abduction','hip_adduction','elbow_flexion','elbow_extension','shoulder_abduction','shoulder_flexion','shoulder_extension','calf_raise','core_flexion','anti_extension','anti_rotation','rotation','carry','other'])),
  CONSTRAINT bulk_exercises_category_ck CHECK (category IN ('strength','bodyweight','core','carry')),
  CONSTRAINT bulk_exercises_unilateral_ck CHECK (default_unilateral_mode IN ('bilateral','unilateral') AND (supports_unilateral OR default_unilateral_mode = 'bilateral')),
  CONSTRAINT bulk_exercises_experience_ck CHECK (min_experience IN ('beginner','intermediate','advanced')),
  CONSTRAINT bulk_exercises_origin_ck CHECK ((is_system AND owner_id IS NULL AND id LIKE 'system:%') OR (NOT is_system AND owner_id IS NOT NULL AND id LIKE 'custom:%'))
);

CREATE UNIQUE INDEX bulk_exercises_system_slug_uidx ON public.bulk_exercises(slug) WHERE is_system;
CREATE UNIQUE INDEX bulk_exercises_owner_slug_uidx ON public.bulk_exercises(owner_id, slug) WHERE NOT is_system;
CREATE INDEX bulk_exercises_name_idx ON public.bulk_exercises(lower(name));
CREATE INDEX bulk_exercises_primary_muscle_idx ON public.bulk_exercises(primary_muscle);
CREATE INDEX bulk_exercises_equipment_idx ON public.bulk_exercises USING gin(equipment);
CREATE INDEX bulk_exercises_owner_idx ON public.bulk_exercises(owner_id) WHERE owner_id IS NOT NULL;
CREATE TRIGGER bulk_exercises_touch BEFORE UPDATE ON public.bulk_exercises
FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();

CREATE FUNCTION private.has_active_bulk()
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = ''
AS $function$
  SELECT (SELECT auth.uid()) IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.bulk_members
    WHERE user_id = (SELECT auth.uid()) AND role = 'owner'
  )
$function$;

REVOKE ALL ON FUNCTION private.has_active_bulk() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION private.has_active_bulk() TO authenticated, service_role;

ALTER TABLE public.bulk_exercises ENABLE ROW LEVEL SECURITY;
CREATE POLICY "bulk exercises read library" ON public.bulk_exercises
FOR SELECT TO authenticated
USING (private.has_active_bulk() AND (is_system OR owner_id = (SELECT auth.uid())));
CREATE POLICY "bulk exercises create own custom" ON public.bulk_exercises
FOR INSERT TO authenticated
WITH CHECK (private.has_active_bulk() AND NOT is_system AND owner_id = (SELECT auth.uid()));
CREATE POLICY "bulk exercises update own custom" ON public.bulk_exercises
FOR UPDATE TO authenticated
USING (private.has_active_bulk() AND NOT is_system AND owner_id = (SELECT auth.uid()))
WITH CHECK (private.has_active_bulk() AND NOT is_system AND owner_id = (SELECT auth.uid()));
CREATE POLICY "bulk exercises delete own custom" ON public.bulk_exercises
FOR DELETE TO authenticated
USING (private.has_active_bulk() AND NOT is_system AND owner_id = (SELECT auth.uid()));

GRANT SELECT, INSERT, UPDATE, DELETE ON public.bulk_exercises TO authenticated;
GRANT ALL ON public.bulk_exercises TO service_role;

CREATE TEMP TABLE bulk_exercise_seed (
  slug text, name text, primary_muscle text, secondary_muscles text[], equipment text[],
  movement_pattern text, category text, supports_unilateral boolean,
  default_unilateral_mode text, is_bodyweight boolean, min_experience text
);

  id, owner_id, slug, name, primary_muscle, secondary_muscles, equipment,
  movement_pattern, category, supports_unilateral, default_unilateral_mode,
  is_bodyweight, is_system, active, min_experience
)
SELECT
  'system:' || slug, NULL, slug, name, primary_muscle, secondary_muscles, equipment,
  movement_pattern, category, supports_unilateral, default_unilateral_mode,
  is_bodyweight, true, true, min_experience
FROM bulk_exercise_seed
ON CONFLICT (id) DO UPDATE SET
  slug = EXCLUDED.slug,
  name = EXCLUDED.name,
  primary_muscle = EXCLUDED.primary_muscle,
  secondary_muscles = EXCLUDED.secondary_muscles,
  equipment = EXCLUDED.equipment,
  movement_pattern = EXCLUDED.movement_pattern,
  category = EXCLUDED.category,
  supports_unilateral = EXCLUDED.supports_unilateral,
  default_unilateral_mode = EXCLUDED.default_unilateral_mode,
  is_bodyweight = EXCLUDED.is_bodyweight,
  active = true,
  min_experience = EXCLUDED.min_experience;

-- Correct equipment for mixed variation families while keeping one canonical row per movement.
UPDATE public.bulk_exercises AS exercise
SET equipment = correction.equipment
FROM (VALUES
  ('system:machine-lat-pulldown', ARRAY['machine']::text[]),
  ('system:dumbbell-pullover', ARRAY['dumbbell','bench']::text[]),
  ('system:machine-pullover', ARRAY['machine']::text[]),
